import pandas as pd
import numpy as np

class Node:
    def __init__(self, feature=None, threshold=None, left=None, right=None, *, value=None):
        self.feature = feature
        self.threshold = threshold
        self.left = left
        self.right = right
        self.value = value
    def is_leaf(self): return self.value is not None

class DecisionTree:
    def __init__(self, max_depth=10, min_samples_split=2):
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
    def fit(self, X, y):
        self.root = self._grow(X, y)
    def _grow(self, X, y, depth=0):
        if depth >= self.max_depth or len(y) < self.min_samples_split or len(np.unique(y)) == 1:
            return Node(value=np.bincount(y).argmax())
        best_gain = -1; split_idx = None; split_thresh = None
        parent_ent = self._entropy(y)
        for i in range(X.shape[1]):
            threshs = np.unique(X[:, i])
            if len(threshs) > 10: threshs = np.percentile(threshs, np.linspace(0, 100, 12)[1:-1])
            for t in threshs:
                left = y[X[:, i] <= t]
                right = y[X[:, i] > t]
                if len(left) == 0 or len(right) == 0: continue
                gain = parent_ent - (len(left)/len(y)*self._entropy(left) + len(right)/len(y)*self._entropy(right))
                if gain > best_gain:
                    best_gain = gain; split_idx = i; split_thresh = t
        if best_gain <= 0:
            return Node(value=np.bincount(y).argmax())
        l_idx = X[:, split_idx] <= split_thresh
        r_idx = X[:, split_idx] > split_thresh
        left_node = self._grow(X[l_idx], y[l_idx], depth+1)
        right_node = self._grow(X[r_idx], y[r_idx], depth+1)
        return Node(split_idx, split_thresh, left_node, right_node)
    def _entropy(self, y):
        ps = np.bincount(y) / len(y)
        return -np.sum([p * np.log2(p) for p in ps if p > 0])
    def predict(self, X):
        return np.array([self._traverse(x, self.root) for x in X])
    def _traverse(self, x, node):
        if node.is_leaf(): return node.value
        if x[node.feature] <= node.threshold: return self._traverse(x, node.left)
        return self._traverse(x, node.right)

